-- Energy is a Character attribute the server drives; it regenerates passively (KaijuData.EnergyRegen).
-- There is NO client "restore energy" remote, so the only real lever is: don't spend energy you don't
-- have. We read each kaiju's real per-skill Energy costs from KaijuData and gate firing on them.
local function getEnergy()
    for _, c in ipairs({ lp.Character, liveModel() }) do
        if c then
            local e = c:GetAttribute("Energy")
            if e ~= nil then return e, (c:GetAttribute("MaxEnergy") or 100) end
        end
    end
    -- fallback: read the HUD bar itself -> Hud.Down.Utility_List.Energy.TextLabel = "Energy [X/Y]"
    local pg = lp:FindFirstChild("PlayerGui")
    local hud = pg and pg:FindFirstChild("Hud")
    local en = hud and hud:FindFirstChild("Energy", true)
    local tl = en and en:FindFirstChild("TextLabel")
    if tl then
        local cur, max = tostring(tl.Text):match("(%d+%.?%d*)%s*/%s*(%d+%.?%d*)")
        if cur and max then return tonumber(cur), tonumber(max) end
    end
    return nil, nil
end
