local function buildingPos(m) local ok, p = pcall(function() return m:GetPivot().Position end); return ok and p or nil end
local function destroyed(m)
    if not m.Parent then return true end
    if m:GetAttribute("IsDestroying") == true then return true end
    local h = m:GetAttribute("Health")
    return h ~= nil and h <= 0
end

local TYPE_ATTRS = { "Type", "BuildingType", "Category", "Class", "Kind", "Model" }
local function typeOf(m)
    for _, a in ipairs(TYPE_ATTRS) do
        local v = m:GetAttribute(a)
        if type(v) == "string" and v ~= "" then return v end
    end
    local n = m.Name:gsub("[%s_%-]*%d+$", "")
    if n == "" then n = m.Name end
    return n
end

-- Containers (Container2/4/5) spawn/replicate heavy and crash low-end when farmed; never target them.
local function isContainer(m)
    return typeOf(m):lower():find("container") ~= nil or m.Name:lower():find("container") ~= nil
end

local function selectedTypeSet()
    local dd = Opt.k_types
    local v = dd and dd.Value
    if type(v) ~= "table" then return nil end
    local set, any = {}, false
    for k, val in pairs(v) do
        if val == true then set[k] = true; any = true
        elseif type(val) == "string" then set[val] = true; any = true end
    end
    return any and set or nil
end

local function getBuildings()
    local map = Workspace:FindFirstChild("Map")
    local city = map and map:FindFirstChild("CityFolder")
    if not city then return {} end
    local center = islandCF[Opt.k_island.Value].Position
    local want = selectedTypeSet()
    local out = {}
    for _, m in ipairs(city:GetChildren()) do
        if m:IsA("Model") and m:GetAttribute("Health") ~= nil and not destroyed(m) and not isContainer(m) then
            if (not want) or want[typeOf(m)] then
                local p = buildingPos(m)
                if p and (p - center).Magnitude < 900 then out[#out + 1] = { m = m, p = p } end
            end
        end
    end
    return out
end

local function discoverTypes()
    local map = Workspace:FindFirstChild("Map")
    local city = map and map:FindFirstChild("CityFolder")
    local counts = {}
    if city then
        local center = islandCF[Opt.k_island.Value].Position
        for _, m in ipairs(city:GetChildren()) do
            if m:IsA("Model") and m:GetAttribute("Health") ~= nil and not isContainer(m) then
                local p = buildingPos(m)
                if p and (p - center).Magnitude < 900 then
                    local t = typeOf(m)
                    counts[t] = (counts[t] or 0) + 1
                end
            end
        end
    end
    local list = {}
    for t in pairs(counts) do list[#list + 1] = t end
    table.sort(list)
    return list, counts
end

local function discoverSkills()
    local pg = lp:FindFirstChild("PlayerGui")
    local sl = pg and pg:FindFirstChild("Skill_List", true)
    local names = {}
    if sl then
        for _, b in ipairs(sl:GetChildren()) do
            if b:IsA("ImageButton") or b:IsA("TextButton") then names[#names + 1] = b.Name end
        end
    end
    if #names == 0 then names = { "Attack1", "Attack2", "Attack3", "Attack4", "Attack5", "Roar1", "Roar2", "Utility" } end
    table.sort(names)
    return names
end

local function selectedSkills(ddKey)
    local dd = Opt[ddKey or "k_skills"]
    local v = dd and dd.Value
