local firedAt = {}
local function skillReady(key)
    if _G.__kaijuSkills and _G.__kaijuSkills.cooldownOf then
        local exists, ready = _G.__kaijuSkills.cooldownOf(key)
        if exists and not ready then return false end
    else
        local sl = skillListFrame()
        local frame = sl and sl:FindFirstChild(key)
        if frame then
            local cd = frame:FindFirstChild("Cooldown")
            local txt = ((cd and cd:IsA("TextLabel") and cd.Text) or ""):gsub("%s", "")
            if txt ~= "" and txt:match("%d") then return false end
        end
    end
    if firedAt[key] and os.clock() - firedAt[key] < 0.35 then return false end
    return true
end

local rrIdx = 0
local sameKeyStreak, lastFiredKey = 0, nil
local function fireReadySkill(ddKey)
    local sk = selectedSkills(ddKey)
    local aware = Toggles.k_autofix and Toggles.k_autofix.Value           -- Smart Energy on
    local e = aware and (getEnergy()) or nil                              -- current energy (nil = unknown)
    for _ = 1, #sk do
        rrIdx = rrIdx % #sk + 1
        local key = sk[rrIdx]
        -- skip attacks we can't afford so energy regenerates instead of being wasted on a dead cast
        if skillReady(key) and (not aware or e == nil or skillCost(key) <= e) then
            firedAt[key] = os.clock()
            if key == lastFiredKey then sameKeyStreak = sameKeyStreak + 1 else sameKeyStreak, lastFiredKey = 1, key end
            pcall(function() CombatRemote:FireServer("UseSkill", key) end)
            return key
        end
    end
    return nil
end

-- Grounded farm positioning: raycast down to the map surface so we stand ON the ground next to a
-- building instead of snapping to its pivot height (which embeds us in geometry). No farm noclip is
-- used (that left you phasing through mountains); instead we hop 300 studs up after each kill.
local farmRay = RaycastParams.new()
farmRay.FilterType = Enum.RaycastFilterType.Exclude
local function groundY(x, z, fallback)
    farmRay.FilterDescendantsInstances = { liveModel() }
    local hit = Workspace:Raycast(Vector3.new(x, (fallback or 0) + 300, z), Vector3.new(0, -2000, 0), farmRay)
    return (hit and hit.Position.Y) or fallback
end
local function cframeFor(b)
    local off = (Opt.k_offset and Opt.k_offset.Value) or 5
    local hx, hz = b.p.X, b.p.Z + off
    local gy = groundY(hx, hz, b.p.Y) + 6
    return CFrame.lookAt(Vector3.new(hx, gy, hz), Vector3.new(b.p.X, gy, b.p.Z))
end

local beamActive = false
track(CombatRemote.OnClientEvent:Connect(function(action, v)
    if action == "DoBeam" then beamActive = (v == true) end
end))
local function moveTo(cf)
    local rp = rootPart()
    if not rp then return end
    if (rp.Position - cf.Position).Magnitude > 4 then rp.CFrame = cf end
    rp.AssemblyLinearVelocity = Vector3.zero
    rp.AssemblyAngularVelocity = Vector3.zero
end
-- Shared noclip that REMEMBERS each part's original collision so it can be restored. Turning a farm
-- (or the manual toggle) off must never leave you phasing through mountains. Records only parts that
-- were collidable; restoreClip() puts them back and is called whenever every noclip source is off.
local collideOrig = setmetatable({}, { __mode = "k" })
local function noclipChar()
    local c = liveModel(); if not c then return end
    for _, p in ipairs(c:GetDescendants()) do
        if p:IsA("BasePart") and p.CanCollide then
            if collideOrig[p] == nil then collideOrig[p] = true end
            p.CanCollide = false
        end
    end
end
local function restoreClip()
    for p, v in pairs(collideOrig) do pcall(function() if p.Parent then p.CanCollide = v end end) end
    collideOrig = setmetatable({}, { __mode = "k" })
end
-- restore only when nothing still wants noclip (manual toggle / pvp positioning)
local function maybeRestoreClip()
    if farming then return end
    if pvpFarming then return end
    if Toggles.k_noclip and Toggles.k_noclip.Value then return end
    if Toggles.k_bossfarm and Toggles.k_bossfarm.Value then return end
    restoreClip()
end
-- ANTI-FLING: big kaiju (e.g. Godzilla Ultima) overlap building geometry when we hard-snap next to them,
-- and the physics solver ejects the huge model skyward. Zeroing velocity every frame while farming
-- cancels that impulse before it builds up, so you don't get launched into the sky.
track(RunService.Heartbeat:Connect(function()
    if not farming or archBusy then return end
    local rp = rootPart()
    if rp then rp.AssemblyLinearVelocity = Vector3.zero; rp.AssemblyAngularVelocity = Vector3.zero end
end))

