PvpBox:AddSlider("k_esp_dist", { Text = "ESP Distance", Default = 2500, Min = 100, Max = 5000, Rounding = 0, Suffix = " studs", Tooltip = "Only show ESP for players within this many studs (streaming caps how far anyone loads anyway)." })
PvpBox:AddDivider()
