local function antiLagOn() return Toggles.k_antilag and Toggles.k_antilag.Value end
local function applyAntiLag(o)
    if o:IsA("ParticleEmitter") or o:IsA("Trail") then
        pcall(function() o.Lifetime = NumberRange.new(0) end)
        pcall(function() o.Enabled = false end)
    elseif o:IsA("Smoke") or o:IsA("Fire") or o:IsA("Sparkles") or o:IsA("Beam") then
        pcall(function() o:Destroy() end)
    elseif o:IsA("BasePart") then
        pcall(function() o.CastShadow = false end)
        pcall(function() o.Material = Enum.Material.Plastic end)
        pcall(function() o.Reflectance = 0 end)
    elseif o:IsA("Decal") or o:IsA("Texture") then
        pcall(function() o.Transparency = 1 end)
    end
end
local antiLagConn
local function setAntiLag(on)
    if antiLagConn then antiLagConn:Disconnect(); antiLagConn = nil end
    if not on then return end
    local Lighting = game:GetService("Lighting")
    pcall(function() Lighting.GlobalShadows = false end)
    pcall(function() Lighting.FogEnd = 9e9 end)
    pcall(function() Lighting.FogStart = 9e9 end)
    pcall(function() settings().Rendering.QualityLevel = 1 end)
    for _, e in ipairs(Lighting:GetDescendants()) do
        if e:IsA("PostEffect") then pcall(function() e.Enabled = false end) end
    end
    pcall(function()
        local t = Workspace.Terrain
        t.WaterWaveSize = 0; t.WaterWaveSpeed = 0; t.WaterReflectance = 0; t.WaterTransparency = 1
    end)
    antiLagConn = track(Workspace.DescendantAdded:Connect(function(o)
        if antiLagOn() then applyAntiLag(o) end
    end))
    task.spawn(function()
        local n = 0
        for _, o in ipairs(Workspace:GetDescendants()) do
            if not antiLagOn() then break end
            applyAntiLag(o)
            n = n + 1
            if n % 400 == 0 then RunService.Heartbeat:Wait() end
        end
    end)
    task.spawn(function()
        while antiLagOn() do
            local terrain = Workspace:FindFirstChildOfClass("Terrain")
            if terrain then for _, o in ipairs(terrain:GetDescendants()) do applyAntiLag(o) end end
            task.wait(1)
        end
    end)
end

