-- VOTE KICK: VoteRemote:FireServer("StartVote", name) opens a kick vote; ("Vote", name, true/false)
-- casts. Incoming votes arrive as OnClientEvent("NewVote", targetName, starterId, cooldown, needed).
-- Scoped in a do-block to keep its locals off the main chunk's 200-local budget.
do
    local VoteRemote = Remotes:FindFirstChild("VoteRemote")
    local VoteBox = SettingsTab:AddRightGroupbox("Vote Kick")
    VoteBox:AddDropdown("k_vote_target", { Values = {}, Default = "", AllowNull = true, Text = "Player" })
    VoteBox:AddButton({ Text = "Start Vote Kick", Func = function()
        local name = Opt.k_vote_target and Opt.k_vote_target.Value
        if not name or name == "" then notify("Pick a player"); return end
        if not VoteRemote then notify("No vote remote"); return end
        pcall(function() VoteRemote:FireServer("StartVote", name) end)
        task.wait(0.3)
        pcall(function() VoteRemote:FireServer("Vote", name, true) end)   -- cast your own yes on it
        notify("Vote kick started on " .. name)
    end })
    VoteBox:AddToggle("k_vote_target_auto", { Text = "Keep Voting Target", Default = false, Tooltip = "Repeatedly opens a kick vote on the selected player whenever no vote is active (respects the game's cooldown)." })
    VoteBox:AddDropdown("k_vote_exclude", { Values = {}, Default = {}, Multi = true, AllowNull = true, Text = "Exclude (never kick)", Tooltip = "Players here are protected: Kick Everyone won't vote them, and Auto-Agree won't vote yes on a kick against them." })
    VoteBox:AddToggle("k_vote_all", { Text = "Kick Everyone (except excluded)", Default = false, Tooltip = "Cycles a kick vote against every player NOT in the Exclude list, one at a time (respects the game's cooldown)." })
    VoteBox:AddToggle("k_vote_auto", { Text = "Auto-Agree All Kicks", Default = false, Tooltip = "Auto-votes YES on every kick vote that starts (skips anyone in the Exclude list)." })
    -- lowercased set of protected players
    local function excludeSet()
        local dd = Opt.k_vote_exclude; local v = dd and dd.Value
        if type(v) ~= "table" then return nil end
        local set, any = {}, false
        for k, val in pairs(v) do
            if val == true then set[k:lower()] = true; any = true
            elseif type(val) == "string" then set[val:lower()] = true; any = true end
        end
        return any and set or nil
    end
    if VoteRemote then
        track(VoteRemote.OnClientEvent:Connect(function(action, target)
            if action == "NewVote" and type(target) == "string" and target ~= lp.Name   -- never vote to kick yourself
                and Toggles.k_vote_auto and Toggles.k_vote_auto.Value then
                local ex = excludeSet()
                if not (ex and ex[target:lower()]) then   -- don't vote yes on a protected player
                    task.wait(0.2)
                    pcall(function() VoteRemote:FireServer("Vote", target, true) end)
                end
            end
        end))
        local allIdx = 0
        task.spawn(function()
            while RUNNING do
                if Toggles.k_vote_all and Toggles.k_vote_all.Value then
                    local ex = excludeSet()
                    local targets = {}
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= lp and not (ex and ex[p.Name:lower()]) then targets[#targets + 1] = p.Name end
                    end
                    if #targets > 0 then
                        allIdx = allIdx % #targets + 1   -- rotate one target per cycle
                        local name = targets[allIdx]
                        pcall(function() VoteRemote:FireServer("StartVote", name) end)
                        task.wait(0.3)
                        pcall(function() VoteRemote:FireServer("Vote", name, true) end)
                    end
                    task.wait(15)
                elseif Toggles.k_vote_target_auto and Toggles.k_vote_target_auto.Value then
                    local name = Opt.k_vote_target and Opt.k_vote_target.Value
                    if name and name ~= "" and Players:FindFirstChild(name) then
                        pcall(function() VoteRemote:FireServer("StartVote", name) end)
                        task.wait(0.3)
                        pcall(function() VoteRemote:FireServer("Vote", name, true) end)
                    end
                    task.wait(15)
                else
                    task.wait(1)
                end
            end
        end)
    end
    task.spawn(function()
        local last = ""
        while RUNNING do
            local names = {}
            for _, p in ipairs(Players:GetPlayers()) do if p ~= lp then names[#names + 1] = p.Name end end
            table.sort(names)
            local sig = table.concat(names, "|")
            if sig ~= last then
                last = sig
                pcall(function() Opt.k_vote_target:SetValues(names) end)
                pcall(function() Opt.k_vote_exclude:SetValues(names) end)
            end
            task.wait(2)
        end
    end)
end

local function unload()
    farming = false
    pvpFarming = false
    pcall(function() if _G.__CW_KAIJU_CLEAN then _G.__CW_KAIJU_CLEAN() end end)   -- stop all loops + disconnect handlers
    pcall(function() Library:Unload() end)
end

local MenuBox = SettingsTab:AddRightGroupbox("Menu")
MenuBox:AddLabel("Menu Toggle"):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = "Menu Toggle" })
MenuBox:AddButton("Unload", unload)
Library.ToggleKeybind = Opt.MenuKeybind

do   -- feedback/help subsystem scoped in its own block so its locals don't count against the main chunk's 200-local limit
local DISCORD_INVITE   = "https://discord.gg/YOUR_INVITE_HERE"
local FEEDBACK_URL     = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
local FEEDBACK_VERSION = "combowick-kaiju-2.0"
local _request = request or (syn and syn.request) or http_request
local function fbTrim(s) return (tostring(s or ""):gsub("^%s*(.-)%s*$", "%1")) end
local function fbHWID()
    local ok, id = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
    if ok and type(id) == "string" and id ~= "" then return id end
    return tostring(lp and lp.UserId or 0)
end
local FB_HWID = fbHWID()
local FB_ERRMAP = {
    empty = "The message is empty.", no_links = "Links are not allowed.",
    too_long = "The message is too long (500 characters maximum).",
    rate_limited = "You have reached the limit of 3 messages. Please try again later.",
    busy = "The server is busy. Please try again.", banned = "You are not allowed to send feedback.",
    discord_error = "Sending failed. Please try again.", network = "Network error.",
    no_request = "Your executor cannot send requests.", bad_response = "The server returned an unexpected response.",
    unreachable = "Your executor cannot reach the server (TLS error). Please try a different executor.",
}
local function sendFeedback(ftype, msg)
    if not _request then return false, "no_request" end
    local ok, res = pcall(function()
        return _request({
            Url = FEEDBACK_URL, Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = HttpService:JSONEncode({
                type = ftype, message = msg, hwid = FB_HWID,
                placeId = tostring(game.PlaceId), username = lp and lp.Name or "?",
                version = FEEDBACK_VERSION,
            }),
        })
    end)
    if not ok or not res then return false, "network" end
    if type(res) == "string" then return false, "unreachable" end
    if type(res) ~= "table" then return false, "network" end
    local code = res.StatusCode or res.status_code or res.Status or res.status
    if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. tostring(code) end
    local body = res.Body or res.body
    if type(body) ~= "string" or body == "" then return false, "bad_response" end
    local dok, data = pcall(function() return HttpService:JSONDecode(body) end)
    if not dok or type(data) ~= "table" then return false, "bad_response" end
    if data.success == true then return true end
    return false, tostring(data.error or "unknown")
end

local FG = SuggestTab:AddLeftGroupbox("Suggestions / Help", "message-square")
FG:AddDropdown("FeedbackType", { Text = "Type", Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion", Callback = function() end })
FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = "Message", Placeholder = "Type your message (500 characters maximum, no links)" })
local fbStatus = FG:AddLabel("", true)
local FEEDBACK_COOLDOWN, lastFeedback = 20, 0
FG:AddButton({
    Text = "Send",
    Func = function()
        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            pcall(function() fbStatus:SetText(string.format("Please wait %d seconds before sending again.", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
            return
        end
        local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
        local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
        if msg == "" then pcall(function() fbStatus:SetText("The message is empty.") end); return end
        if #msg > 500 then pcall(function() fbStatus:SetText("The message is too long (500 characters maximum).") end); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            pcall(function() fbStatus:SetText("Links are not allowed.") end); return
        end
        pcall(function() fbStatus:SetText("Sending...") end)
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                pcall(function() fbStatus:SetText("Sent. Thank you!") end)
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
                notify("Your feedback was sent. Thank you!")
            else
                pcall(function() fbStatus:SetText(FB_ERRMAP[err] or ("Failed to send: " .. tostring(err))) end)
            end
        end)
    end,
})
FG:AddLabel("Maximum 3 messages per hour. No links or mentions.", true)
local HelpGroup = SuggestTab:AddRightGroupbox("Help / FAQ", "life-buoy")
HelpGroup:AddButton({ Text = "Join Discord", Tooltip = DISCORD_INVITE, Func = function()
    pcall(function() setclipboard(DISCORD_INVITE) end)
    notify("Discord link copied. Paste it into your browser.")
end })
HelpGroup:AddDivider()
HelpGroup:AddLabel("Have a suggestion or found a bug?\nChoose a type, type your message, and press Send.", true)
end   -- end feedback/help subsystem block

